// ─── modelos/formato.js ──────────────────────────────────────────────────────────────────────
// Fechas y textos que comparten todos los flujos. Las fechas viajan como texto ISO
// (AAAA-MM-DD o fecha y hora con zona) para que las funciones sean fáciles de probar.

/** 2026-10-07 → «07/10/2026». */
const fecha = (iso) => DateTime.fromISO(iso).toFormat('dd/MM/yyyy');

/** 2026-10-07 → «7 de oct». */
const fechaCorta = (iso) => DateTime.fromISO(iso).setLocale('es').toFormat("d 'de' LLL");

/** Fecha y hora conservando la zona horaria con la que se guardó: «13/10/2026 a las 10:56». */
const fechaHora = (iso) => DateTime.fromISO(iso, { setZone: true }).setLocale('es').toFormat("dd/MM/yyyy 'a las' HH:mm");

/** Días enteros entre dos fechas ISO (negativo si `hasta` es anterior). */
const diasEntre = (desde, hasta) => Math.round(DateTime.fromISO(hasta).diff(DateTime.fromISO(desde), 'days').days);

/** Suma (o resta) días a una fecha ISO. */
const sumarDias = (iso, dias) => DateTime.fromISO(iso).plus({ days: dias }).toISODate();

/** Minutos enteros entre dos instantes ISO. */
const minutosEntre = (desde, hasta) => Math.round(DateTime.fromISO(hasta).diff(DateTime.fromISO(desde), 'minutes').minutes);

/** «2026-05» → «Mayo 2026». */
const mes = (aaaaMm) => mayuscula(DateTime.fromISO(`${aaaaMm}-01`).setLocale('es').toFormat('LLLL yyyy'));

/** «Del 7 al 13 de octubre de 2026» o «Del 30 de septiembre al 6 de octubre de 2026». */
function rangoFechas(inicioIso, finIso) {
  const a = DateTime.fromISO(inicioIso).setLocale('es');
  const b = DateTime.fromISO(finIso).setLocale('es');
  const inicio = a.month === b.month && a.year === b.year ? a.toFormat('d')
    : a.year === b.year ? a.toFormat("d 'de' LLLL")
      : a.toFormat("d 'de' LLLL 'de' yyyy");
  return `Del ${inicio} al ${b.toFormat("d 'de' LLLL 'de' yyyy")}`;
}

/** 0 → «hoy», 1 → «mañana», 3 → «en 3 días». */
const cuando = (dias) => (dias === 0 ? 'hoy' : dias === 1 ? 'mañana' : `en ${dias} días`);

/** 1 → «ayer», 6 → «hace 6 días». */
const hace = (dias) => (dias === 1 ? 'ayer' : `hace ${dias} días`);

/** 1 → «1 préstamo», 3 → «3 préstamos». */
const plural = (n, uno, varios) => `${n} ${n === 1 ? uno : varios}`;

/** Primera letra en mayúscula. */
const mayuscula = (s) => s[0].toUpperCase() + s.slice(1);

/** 75 → «1 h 15 min», 1 → «1 minuto». */
const duracion = (minutos) => (minutos < 60
  ? plural(minutos, 'minuto', 'minutos')
  : `${Math.floor(minutos / 60)} h ${minutos % 60} min`);

// ─── modelos/prestamos.js ────────────────────────────────────────────────────────────────────
// Reglas de los recordatorios: a quién avisar, de qué, y cómo recordar lo ya avisado.
//
// La «memoria» son los datos estáticos del flujo en n8n (solo se guardan con el flujo activado):
//   memoria.porVencer[idPrestamo] = fecha límite de la que ya se avisó
//   memoria.vencidos[idPrestamo]  = día del último aviso de vencido (AAAA-MM-DD)

/** Prepara la memoria la primera vez y olvida los préstamos que ya no están pendientes. */
function limpiarMemoria(memoria, pendientes) {
  memoria.porVencer ??= {};
  memoria.vencidos ??= {};
  const vigentes = new Set(pendientes.map((p) => String(p.id)));
  for (const lista of [memoria.porVencer, memoria.vencidos]) {
    for (const id of Object.keys(lista)) if (!vigentes.has(id)) delete lista[id];
  }
  return memoria;
}

/**
 * Préstamos que toca avisar hoy, agrupados por usuario.
 *   - vencido: si nunca se avisó, o si el último aviso fue hace `repetirVencidosCadaDias` días o más
 *   - por vencer: si faltan `diasAntesDeVencer` días o menos y no se avisó de esa fecha límite
 *     (si se renueva, la fecha cambia y se vuelve a avisar cuando toque)
 * Los usuarios sin correo se descartan.
 * @returns {{ usuario, vencidos: object[], porVencer: object[] }[]}
 */
function avisosPendientes({ vencidos, enPlazo, usuarios, memoria, hoy, diasAntesDeVencer, repetirVencidosCadaDias }) {
  const porUsuario = new Map();
  const anotar = (p, tipo) => {
    if (!porUsuario.has(p.memberId)) porUsuario.set(p.memberId, { vencidos: [], porVencer: [] });
    porUsuario.get(p.memberId)[tipo].push(p);
  };

  for (const p of vencidos) {
    const ultimo = memoria.vencidos?.[p.id];
    if (!ultimo || diasEntre(ultimo, hoy) >= repetirVencidosCadaDias) anotar(p, 'vencidos');
  }
  for (const p of enPlazo) {
    if (diasEntre(hoy, p.dueDate) <= diasAntesDeVencer && memoria.porVencer?.[p.id] !== p.dueDate) anotar(p, 'porVencer');
  }

  const fichas = new Map(usuarios.map((u) => [u.id, u]));
  return [...porUsuario]
    .map(([id, avisos]) => ({ usuario: fichas.get(id), ...avisos }))
    .filter((a) => a.usuario?.email);
}

/** Lista plana de los avisos de un usuario, para guardarla junto al correo. */
const listaDeAvisos = ({ vencidos, porVencer }) => [
  ...vencidos.map((p) => ({ prestamo: p.id, tipo: 'vencido', libro: p.bookTitle, vence: p.dueDate })),
  ...porVencer.map((p) => ({ prestamo: p.id, tipo: 'porVencer', libro: p.bookTitle, vence: p.dueDate })),
];

/** Apunta en la memoria los avisos de un correo que se envió bien. */
function registrarEnvio(memoria, avisos, hoy) {
  memoria.porVencer ??= {};
  memoria.vencidos ??= {};
  for (const aviso of avisos) {
    if (aviso.tipo === 'vencido') memoria.vencidos[aviso.prestamo] = hoy;
    else memoria.porVencer[aviso.prestamo] = aviso.vence;
  }
  return memoria;
}

/** ¿Se puede renovar ya? (la API indica desde qué día: `renewableFrom`). */
const esRenovable = (prestamo, hoy) => Boolean(prestamo.renewableFrom && prestamo.renewableFrom <= hoy);

// ─── vistas/html.js ──────────────────────────────────────────────────────────────────────────
// Utilidades HTML comunes a todas las vistas.

/** Escapa un texto para insertarlo en HTML (nombres y títulos vienen de la base de datos). */
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

// ─── vistas/plantilla-correo.js ──────────────────────────────────────────────────────────────
// Plantilla común de los correos: cabecera con degradado, tarjeta blanca, pie y piezas reutilizables.
// Usa los colores de la web de la biblioteca. Todo va con estilos en línea y tablas: es lo único
// que respetan por igual Gmail, Outlook y los clientes de móvil.

const COLOR = {
  marca: '#4f46e5', marca2: '#7c3aed', marcaSuave: '#eef2ff',
  texto: '#0f172a', suave: '#64748b', borde: '#e2e8f0', fondo: '#f1f5f9', tarjeta: '#ffffff', sutil: '#f8fafc',
  peligro: '#dc2626', peligroSuave: '#fef2f2', peligroBorde: '#fecaca',
  aviso: '#b45309', avisoSuave: '#fffbeb', avisoBorde: '#fde68a',
  exito: '#047857', exitoSuave: '#ecfdf5', exitoBorde: '#a7f3d0',
};
/** Color vivo de las líneas laterales de tarjetas y recuadros. */
const ACENTO = { peligro: '#ef4444', aviso: '#f59e0b', exito: '#10b981', marca: COLOR.marca, neutro: '#94a3b8' };
/** [texto, fondo, borde] de cada tono. */
const TONOS = {
  peligro: [COLOR.peligro, COLOR.peligroSuave, COLOR.peligroBorde],
  aviso: [COLOR.aviso, COLOR.avisoSuave, COLOR.avisoBorde],
  exito: [COLOR.exito, COLOR.exitoSuave, COLOR.exitoBorde],
  marca: [COLOR.marca, COLOR.marcaSuave, '#c7d2fe'],
  neutro: [COLOR.suave, COLOR.sutil, COLOR.borde],
};
const FUENTE = "-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif";

/** Etiqueta redondeada de estado («Vencido hace 6 días»). */
const pastilla = (texto, tono = 'neutro') => {
  const [color, fondo, borde] = TONOS[tono];
  return `<span style="display:inline-block;padding:3px 10px;border-radius:999px;background:${fondo};border:1px solid ${borde};color:${color};font-size:12px;font-weight:600;line-height:18px;white-space:nowrap">${esc(texto)}</span>`;
};

/** Recuadro de color para mensajes importantes. */
const recuadro = (html, tono = 'marca', margen = '20px 0 0') => {
  const [, fondo, borde] = TONOS[tono];
  return `<table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="margin:${margen}"><tr>
<td style="background:${fondo};border:1px solid ${borde};border-left:4px solid ${ACENTO[tono]};border-radius:8px;padding:12px 16px;font-size:14px;line-height:21px;color:${COLOR.texto}">${html}</td></tr></table>`;
};

/** Título de sección dentro del cuerpo, con contador opcional. */
const seccion = (titulo, cantidad) => `<h2 style="margin:28px 0 10px;font-size:15px;line-height:22px;font-weight:700;color:${COLOR.texto}">${esc(titulo)}${
  cantidad === undefined ? '' : ` <span style="display:inline-block;margin-left:4px;padding:0 8px;border-radius:999px;background:${COLOR.marcaSuave};color:${COLOR.marca};font-size:12px;line-height:20px;vertical-align:1px">${cantidad}</span>`}</h2>`;

/**
 * Documento completo del correo.
 * @param o.etiqueta    texto pequeño sobre el título («RECORDATORIO DE PRÉSTAMOS»)
 * @param o.vistaPrevia texto que muestran los clientes de correo junto al asunto
 * @param o.cuerpo      HTML del contenido
 * @param o.pie         HTML del pie (ya escapado)
 * @param o.cabecera    color de la cabecera: 'marca' (índigo), 'peligro' (rojo) o 'exito' (verde)
 */
function correoHtml({ biblioteca, etiqueta, titulo, subtitulo = '', vistaPrevia = '', cuerpo, pie, cabecera = 'marca' }) {
  const [desde, hasta, claro] = {
    marca: [COLOR.marca, COLOR.marca2, '#c7d2fe'],
    peligro: ['#dc2626', '#9f1239', '#fecaca'],
    exito: ['#059669', '#0f766e', '#a7f3d0'],
  }[cabecera];
  return `<!doctype html>
<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="color-scheme" content="light"><meta name="supported-color-schemes" content="light"><title>${esc(titulo)}</title></head>
<body style="margin:0;padding:0;background:${COLOR.fondo};-webkit-text-size-adjust:100%">
<div style="display:none;max-height:0;overflow:hidden;opacity:0;color:${COLOR.fondo}">${esc(vistaPrevia)}&#847;&zwnj;&nbsp;&#847;&zwnj;&nbsp;&#847;&zwnj;&nbsp;</div>
<table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="background:${COLOR.fondo}"><tr><td align="center" style="padding:24px 12px">
<table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="max-width:600px;font-family:${FUENTE}">
<tr><td style="background:${desde};background-image:linear-gradient(135deg,${desde},${hasta});border-radius:14px 14px 0 0;padding:24px 28px">
  <table role="presentation" cellspacing="0" cellpadding="0"><tr>
    <td style="width:36px;height:36px;border-radius:10px;background:rgba(255,255,255,0.18);text-align:center;font-size:19px;line-height:36px">&#128214;</td>
    <td style="padding-left:12px;font-size:15px;font-weight:700;color:#ffffff;letter-spacing:0.2px">${esc(biblioteca)}</td>
  </tr></table>
  <div style="margin-top:20px;font-size:12px;font-weight:700;letter-spacing:1.2px;text-transform:uppercase;color:${claro}">${esc(etiqueta)}</div>
  <div style="margin-top:4px;font-size:24px;line-height:31px;font-weight:700;color:#ffffff">${esc(titulo)}</div>
  ${subtitulo ? `<div style="margin-top:6px;font-size:14px;line-height:20px;color:#ffffff;opacity:0.9">${esc(subtitulo)}</div>` : ''}
</td></tr>
<tr><td style="background:${COLOR.tarjeta};border:1px solid ${COLOR.borde};border-top:0;border-radius:0 0 14px 14px;padding:28px;font-size:15px;line-height:23px;color:${COLOR.texto}">
${cuerpo}
</td></tr>
<tr><td style="padding:18px 28px 0;text-align:center;font-size:12px;line-height:18px;color:${COLOR.suave}">${pie}</td></tr>
</table>
</td></tr></table>
</body></html>`;
}

// ─── vistas/correo-recordatorio.js ───────────────────────────────────────────────────────────
// Vista del recordatorio que recibe cada usuario: sus préstamos vencidos y los que vencen pronto.

/** Tarjeta de un préstamo: título, etiqueta de estado, fecha límite y una nota opcional. */
const tarjetaPrestamo = (p, { tono, estado, nota }) => `<table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="margin:0 0 12px"><tr>
<td style="border:1px solid ${COLOR.borde};border-left:4px solid ${ACENTO[tono]};border-radius:10px;padding:14px 16px;background:${COLOR.tarjeta}">
<div style="font-size:16px;line-height:22px;font-weight:700;color:${COLOR.texto}">${esc(p.bookTitle)}</div>
<div style="margin-top:8px;line-height:26px">${pastilla(estado, tono)}<span style="padding-left:8px;font-size:13px;color:${COLOR.suave};white-space:nowrap">Fecha límite: ${fecha(p.dueDate)}</span></div>
${nota ? `<div style="margin-top:8px;font-size:13px;line-height:19px;color:${nota.color}">${nota.html}</div>` : ''}
</td></tr></table>`;

/**
 * @param o.usuario    { name, email }
 * @param o.vencidos   préstamos vencidos de los que toca avisar
 * @param o.porVencer  préstamos que vencen pronto de los que toca avisar
 * @param o.hoy        AAAA-MM-DD
 * @param o.biblioteca nombre de la biblioteca
 * @returns {{ asunto, html, texto }}
 */
function correoRecordatorio({ usuario, vencidos: v, porVencer: pv, hoy, biblioteca }) {
  const quedan = (p) => diasEntre(hoy, p.dueDate); // negativo si ya venció
  const renovar = (p) => (esRenovable(p, hoy)
    ? 'Ya se puede renovar si lo necesitas más tiempo.'
    : `Podrás renovarlo a partir del ${fecha(p.renewableFrom)}.`);

  const titulo = v.length
    ? `Tienes ${plural(v.length, 'préstamo vencido', 'préstamos vencidos')}`
    : pv.length === 1 ? 'Tu préstamo vence pronto' : `Tienes ${pv.length} préstamos que vencen pronto`;
  const asunto = v.length || pv.length > 1 ? titulo : `«${pv[0].bookTitle}» vence ${cuando(quedan(pv[0]))}`;

  // --- HTML ---
  const cuerpo = [`<p style="margin:0 0 16px">Hola, <strong>${esc(usuario.name)}</strong>:</p>`];
  if (v.length) {
    cuerpo.push(
      `<p style="margin:0 0 16px">${v.length === 1 ? 'Este libro ya debería haberse devuelto' : 'Estos libros ya deberían haberse devuelto'}. Por favor, ${v.length === 1 ? 'devuélvelo' : 'devuélvelos'} cuanto antes.</p>`,
      ...v.map((p) => tarjetaPrestamo(p, { tono: 'peligro', estado: mayuscula(`vencido ${hace(-quedan(p))}`) })),
      recuadro('Mientras tengas préstamos vencidos <strong>no podrás llevarte otros libros</strong>.', 'peligro'),
    );
  }
  if (pv.length) {
    if (v.length) cuerpo.push(seccion(pv.length === 1 ? 'Además, vence pronto' : 'Además, vencen pronto', pv.length));
    else cuerpo.push(`<p style="margin:0 0 16px">${pv.length === 1 ? 'Te recordamos que este préstamo vence pronto' : 'Te recordamos que estos préstamos vencen pronto'}:</p>`);
    cuerpo.push(...pv.map((p) => tarjetaPrestamo(p, {
      tono: 'aviso',
      estado: mayuscula(`vence ${cuando(quedan(p))}`),
      nota: esRenovable(p, hoy)
        ? { color: COLOR.exito, html: `&#10003; ${renovar(p)}` }
        : { color: COLOR.suave, html: renovar(p) },
    })));
  }
  cuerpo.push(`<p style="margin:24px 0 0">Un saludo,<br><strong>${esc(biblioteca)}</strong></p>`);

  const primero = v[0] ?? pv[0];
  const html = correoHtml({
    biblioteca,
    etiqueta: 'Recordatorio de préstamos',
    titulo,
    vistaPrevia: v.length
      ? `«${primero.bookTitle}» venció el ${fecha(primero.dueDate)}. Devuélvelo cuanto antes.`
      : `«${primero.bookTitle}» vence el ${fecha(primero.dueDate)}.`,
    cuerpo: cuerpo.join('\n'),
    pie: `Mensaje automático de ${esc(biblioteca)}.<br>Si ya devolviste ${v.length + pv.length === 1 ? 'el libro' : 'los libros'}, no tengas en cuenta este aviso.`,
  });

  // --- Texto plano (clientes que no muestran HTML) ---
  const texto = [`Hola, ${usuario.name}:`, ''];
  if (v.length) {
    texto.push(v.length === 1 ? 'Este libro ya debería haberse devuelto:' : 'Estos libros ya deberían haberse devuelto:',
      ...v.map((p) => `- «${p.bookTitle}»: venció el ${fecha(p.dueDate)} (${hace(-quedan(p))}).`), '',
      `Por favor, ${v.length === 1 ? 'devuélvelo' : 'devuélvelos'} cuanto antes. Mientras tengas préstamos vencidos no podrás llevarte otros libros.`, '');
  }
  if (pv.length) {
    const frase = pv.length === 1 ? 'este préstamo vence pronto:' : 'estos préstamos vencen pronto:';
    texto.push(v.length ? `Además, ${frase}` : mayuscula(frase),
      ...pv.map((p) => `- «${p.bookTitle}»: vence ${cuando(quedan(p))}, el ${fecha(p.dueDate)}. ${renovar(p)}`), '');
  }
  texto.push('Un saludo,', biblioteca);

  return { asunto, html, texto: texto.join('\n') };
}

// ─── controladores/recordatorios-preparar.js ─────────────────────────────────────────────────
// Nodo «Preparar avisos» (Recordatorios de préstamos): un correo por usuario con lo que toca avisar hoy.

/**
 * @param n8n.$       acceso a los nodos anteriores
 * @param n8n.hoy     AAAA-MM-DD en la zona horaria del flujo
 * @param n8n.memoria datos estáticos del flujo (qué se avisó ya)
 */
function prepararAvisos({ $, hoy, memoria }) {
  const cfg = $('Configuración').first().json;
  const paginas = (nodo) => $(nodo).all().flatMap((i) => i.json.content ?? []);
  const vencidos = paginas('Préstamos vencidos');
  const enPlazo = paginas('Préstamos en plazo');

  limpiarMemoria(memoria, [...vencidos, ...enPlazo]);
  const pendientes = avisosPendientes({
    vencidos,
    enPlazo,
    usuarios: $('Usuarios').all().map((i) => i.json),
    memoria,
    hoy,
    diasAntesDeVencer: cfg.diasAntesDeVencer,
    repetirVencidosCadaDias: cfg.repetirVencidosCadaDias,
  });

  // Modo de pruebas: todo llega a `correoPruebas` y el asunto indica a quién iba dirigido.
  const enPruebas = Boolean(cfg.correoPruebas);
  return pendientes.map((avisos) => {
    const { usuario } = avisos;
    const { asunto, html, texto } = correoRecordatorio({ ...avisos, hoy, biblioteca: cfg.nombreBiblioteca });
    return {
      json: {
        para: enPruebas ? cfg.correoPruebas : usuario.email,
        asunto: enPruebas ? `[PRUEBA para ${usuario.email}] ${asunto}` : asunto,
        html,
        texto,
        usuario: usuario.name,
        correoUsuario: usuario.email,
        avisos: listaDeAvisos(avisos),
      },
    };
  });
}

return await prepararAvisos({ $, $input, hoy: $today.toISODate(), ahora: $now.toISO(), memoria: $getWorkflowStaticData('global'), helpers: this.helpers });

