// ─── modelos/formato.js ──────────────────────────────────────────────────────────────────────
// Fechas y textos que comparten todos los flujos. Las fechas viajan como texto ISO
// (AAAA-MM-DD o fecha y hora con zona) para que las funciones sean fáciles de probar.

/** 2026-10-07 → «07/10/2026». */
const fecha = (iso) => DateTime.fromISO(iso).toFormat('dd/MM/yyyy');

/** 2026-10-07 → «7 de oct». */
const fechaCorta = (iso) => DateTime.fromISO(iso).setLocale('es').toFormat("d 'de' LLL");

/** Fecha y hora conservando la zona horaria con la que se guardó: «13/10/2026 a las 10:56». */
const fechaHora = (iso) => DateTime.fromISO(iso, { setZone: true }).setLocale('es').toFormat("dd/MM/yyyy 'a las' HH:mm");

/** Días enteros entre dos fechas ISO (negativo si `hasta` es anterior). */
const diasEntre = (desde, hasta) => Math.round(DateTime.fromISO(hasta).diff(DateTime.fromISO(desde), 'days').days);

/** Suma (o resta) días a una fecha ISO. */
const sumarDias = (iso, dias) => DateTime.fromISO(iso).plus({ days: dias }).toISODate();

/** Minutos enteros entre dos instantes ISO. */
const minutosEntre = (desde, hasta) => Math.round(DateTime.fromISO(hasta).diff(DateTime.fromISO(desde), 'minutes').minutes);

/** «2026-05» → «Mayo 2026». */
const mes = (aaaaMm) => mayuscula(DateTime.fromISO(`${aaaaMm}-01`).setLocale('es').toFormat('LLLL yyyy'));

/** «Del 7 al 13 de octubre de 2026» o «Del 30 de septiembre al 6 de octubre de 2026». */
function rangoFechas(inicioIso, finIso) {
  const a = DateTime.fromISO(inicioIso).setLocale('es');
  const b = DateTime.fromISO(finIso).setLocale('es');
  const inicio = a.month === b.month && a.year === b.year ? a.toFormat('d')
    : a.year === b.year ? a.toFormat("d 'de' LLLL")
      : a.toFormat("d 'de' LLLL 'de' yyyy");
  return `Del ${inicio} al ${b.toFormat("d 'de' LLLL 'de' yyyy")}`;
}

/** 0 → «hoy», 1 → «mañana», 3 → «en 3 días». */
const cuando = (dias) => (dias === 0 ? 'hoy' : dias === 1 ? 'mañana' : `en ${dias} días`);

/** 1 → «ayer», 6 → «hace 6 días». */
const hace = (dias) => (dias === 1 ? 'ayer' : `hace ${dias} días`);

/** 1 → «1 préstamo», 3 → «3 préstamos». */
const plural = (n, uno, varios) => `${n} ${n === 1 ? uno : varios}`;

/** Primera letra en mayúscula. */
const mayuscula = (s) => s[0].toUpperCase() + s.slice(1);

/** 75 → «1 h 15 min», 1 → «1 minuto». */
const duracion = (minutos) => (minutos < 60
  ? plural(minutos, 'minuto', 'minutos')
  : `${Math.floor(minutos / 60)} h ${minutos % 60} min`);

// ─── modelos/prestamos.js ────────────────────────────────────────────────────────────────────
// Reglas de los recordatorios: a quién avisar, de qué, y cómo recordar lo ya avisado.
//
// La «memoria» son los datos estáticos del flujo en n8n (solo se guardan con el flujo activado):
//   memoria.porVencer[idPrestamo] = fecha límite de la que ya se avisó
//   memoria.vencidos[idPrestamo]  = día del último aviso de vencido (AAAA-MM-DD)

/** Prepara la memoria la primera vez y olvida los préstamos que ya no están pendientes. */
function limpiarMemoria(memoria, pendientes) {
  memoria.porVencer ??= {};
  memoria.vencidos ??= {};
  const vigentes = new Set(pendientes.map((p) => String(p.id)));
  for (const lista of [memoria.porVencer, memoria.vencidos]) {
    for (const id of Object.keys(lista)) if (!vigentes.has(id)) delete lista[id];
  }
  return memoria;
}

/**
 * Préstamos que toca avisar hoy, agrupados por usuario.
 *   - vencido: si nunca se avisó, o si el último aviso fue hace `repetirVencidosCadaDias` días o más
 *   - por vencer: si faltan `diasAntesDeVencer` días o menos y no se avisó de esa fecha límite
 *     (si se renueva, la fecha cambia y se vuelve a avisar cuando toque)
 * Los usuarios sin correo se descartan.
 * @returns {{ usuario, vencidos: object[], porVencer: object[] }[]}
 */
function avisosPendientes({ vencidos, enPlazo, usuarios, memoria, hoy, diasAntesDeVencer, repetirVencidosCadaDias }) {
  const porUsuario = new Map();
  const anotar = (p, tipo) => {
    if (!porUsuario.has(p.memberId)) porUsuario.set(p.memberId, { vencidos: [], porVencer: [] });
    porUsuario.get(p.memberId)[tipo].push(p);
  };

  for (const p of vencidos) {
    const ultimo = memoria.vencidos?.[p.id];
    if (!ultimo || diasEntre(ultimo, hoy) >= repetirVencidosCadaDias) anotar(p, 'vencidos');
  }
  for (const p of enPlazo) {
    if (diasEntre(hoy, p.dueDate) <= diasAntesDeVencer && memoria.porVencer?.[p.id] !== p.dueDate) anotar(p, 'porVencer');
  }

  const fichas = new Map(usuarios.map((u) => [u.id, u]));
  return [...porUsuario]
    .map(([id, avisos]) => ({ usuario: fichas.get(id), ...avisos }))
    .filter((a) => a.usuario?.email);
}

/** Lista plana de los avisos de un usuario, para guardarla junto al correo. */
const listaDeAvisos = ({ vencidos, porVencer }) => [
  ...vencidos.map((p) => ({ prestamo: p.id, tipo: 'vencido', libro: p.bookTitle, vence: p.dueDate })),
  ...porVencer.map((p) => ({ prestamo: p.id, tipo: 'porVencer', libro: p.bookTitle, vence: p.dueDate })),
];

/** Apunta en la memoria los avisos de un correo que se envió bien. */
function registrarEnvio(memoria, avisos, hoy) {
  memoria.porVencer ??= {};
  memoria.vencidos ??= {};
  for (const aviso of avisos) {
    if (aviso.tipo === 'vencido') memoria.vencidos[aviso.prestamo] = hoy;
    else memoria.porVencer[aviso.prestamo] = aviso.vence;
  }
  return memoria;
}

/** ¿Se puede renovar ya? (la API indica desde qué día: `renewableFrom`). */
const esRenovable = (prestamo, hoy) => Boolean(prestamo.renewableFrom && prestamo.renewableFrom <= hoy);

// ─── controladores/recordatorios-registrar.js ────────────────────────────────────────────────
// Nodo «Registrar envíos» (Recordatorios de préstamos): apunta en la memoria los avisos enviados.
// Los correos que fallan salen por la otra rama («No enviados») y, como no se apuntan aquí,
// se vuelven a intentar en la siguiente ejecución.

function registrarEnvios({ $, $input, hoy, memoria }) {
  return $input.all().map((_, i) => {
    const correo = $('Preparar avisos').itemMatching(i).json;
    registrarEnvio(memoria, correo.avisos, hoy);
    return { json: { usuario: correo.usuario, para: correo.para, asunto: correo.asunto, avisos: correo.avisos.length } };
  });
}

return await registrarEnvios({ $, $input, hoy: $today.toISODate(), ahora: $now.toISO(), memoria: $getWorkflowStaticData('global'), helpers: this.helpers });

