    const { error } = item.json;
    return {
      json: {
        usuario: correo.usuario,
        para: correo.para,
        asunto: correo.asunto,
        motivo: error?.message ?? (typeof error === 'string' ? error : JSON.stringify(item.json)),
      },
    };
  });
}

